import './App.css';
 
function App() {
  return (
    <div className="App">
      <header>
        <h1>문서 저장 및 검색 시스템</h1>
      </header>
      <main>
        <p>React 프로젝트가 시작되었습니다!</p>
      </main>
    </div>
  );
}
 
export default App;
